def esc(s): return html.escape(str(s), quote=True)
def url(slug=''): return BASE + (slug + '/' if slug else '')
def link(slug, text, cls=''): return f'<a href="{url(slug)}" class="{cls}">{esc(text)}</a>'
def picture(name, alt, cls='', lazy=True): return f'<img class="{cls}" src="{BASE}assets/{PHOTO[name]}" alt="{esc(alt)}" width="1400" height="933" '+('loading="lazy"' if lazy else 'fetchpriority="high"')+'>'
def brand(): return '<span class="brand-mark" aria-hidden="true"><i></i><i></i><i></i></span><span class="brand-name">FIREFLY<small>HEATING & COOLING</small></span>'
